package com.studenttong.mobile;
import org.json.*;import java.net.*;import javax.net.ssl.HttpsURLConnection;import java.io.*;import android.os.SystemClock;
public final class LocationSearchManager {
 final Store store;final String aid;static long lastRequest;public LocationSearchManager(Store s,String a){store=s;aid=a;}
 public static String endpoint(String s)throws Exception{URI u=new URI(s);if(!"https".equals(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null)throw new Exception("地理编码服务必须是无凭据的HTTPS根地址");return s.replaceAll("/+$","");}
 synchronized JSONObject cached(String route,String query)throws Exception{String key="geocache."+java.util.UUID.nameUUIDFromBytes((endpoint(store.setting(aid,"geocoder","https://nominatim.openstreetmap.org"))+route+query).getBytes("UTF-8"));String value=store.setting(aid,key,"");if(!value.isEmpty()){JSONObject j=new JSONObject(value);if(System.currentTimeMillis()-j.optLong("time")<86400000)return j;}synchronized(LocationSearchManager.class){long wait=1200-(SystemClock.elapsedRealtime()-lastRequest);if(wait>0)Thread.sleep(wait);lastRequest=SystemClock.elapsedRealtime();}String url=endpoint(store.setting(aid,"geocoder","https://nominatim.openstreetmap.org"))+route+"?format=jsonv2&accept-language=zh-CN&"+query;HttpsURLConnection c=(HttpsURLConnection)new URL(url).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(12000);c.setReadTimeout(15000);c.setRequestProperty("User-Agent","StudentTong/0.3.0 (https://github.com/saldienses/StudentTong)");try{if(c.getResponseCode()!=200)throw new Exception("地点服务不可用，可手动输入坐标");String text;try(InputStream in=c.getInputStream()){text=MainActivity.read(in,1024*1024);}JSONObject j=new JSONObject().put("time",System.currentTimeMillis()).put("value",text);store.setSetting(aid,key,j.toString());return j;}finally{c.disconnect();}}
 public JSONArray search(String query)throws Exception{query=query.trim();if(query.isEmpty()||query.length()>150)throw new Exception("请输入150字以内的地点");JSONArray raw=new JSONArray(cached("/search","limit=6&q="+URLEncoder.encode(query,"UTF-8")).getString("value")),out=new JSONArray();for(int i=0;i<raw.length();i++){JSONObject r=raw.getJSONObject(i);out.put(new PreviewLocation(Double.parseDouble(r.getString("lat")),Double.parseDouble(r.getString("lon")),10,r.optString("display_name")).json());}return out;}
 public String reverse(PreviewLocation p)throws Exception{return new JSONObject(cached("/reverse","lat="+p.latitude+"&lon="+p.longitude).getString("value")).optString("display_name","未找到地址，可保存坐标");}
}
